// 1. Security & Idempotency Validation
const headers = $input.item.json.headers || {};
const body = $input.item.json.body || $input.item.json;

const providedSecret = headers['x-civicos-secret'] || headers['x-n8n-webhook-secret'] || '';
const expectedSecret = $env.N8N_WEBHOOK_SECRET || '';

if (expectedSecret && providedSecret && providedSecret !== expectedSecret) {
  return [{
    json: {
      error: 'Unauthorized: Invalid webhook secret',
      authorized: false,
      status_code: 401
    }
  }];
}

const eventId = body.event_id || `EVT_${body.event || 'UNKNOWN'}_${body.grievance_id || 0}_${Date.now()}`;

return [{
  json: {
    ...body,
    event_id: eventId,
    authorized: true,
    received_at: new Date().toISOString()
  }
}];

// Community Impact Threshold Classifier
const count = $input.item.json.community_count || 0;
let classification = 'NO_CONFIRMATION';
let attention = 'STANDARD';
let action = 'COMMUNITY_TRACKED';
let recommended = 'Standard community impact monitoring';

if (count >= 25) {
  classification = 'MASS_IMPACT';
  attention = 'CRITICAL';
  action = 'CRITICAL_MASS_ESCALATION';
  recommended = 'Severe community impact: 25+ citizens confirmed. Immediate municipal intervention required.';
} else if (count >= 10) {
  classification = 'WIDESPREAD_IMPACT';
  attention = 'HIGH';
  action = 'URGENT_DISTRICT_ALERT';
  recommended = 'Widespread civic issue: 10+ citizens confirmed. Elevate department priority.';
} else if (count >= 5) {
  classification = 'HIGH_COMMUNITY_IMPACT';
  attention = 'HIGH';
  action = 'PRIORITY_QUEUE_BUMP';
  recommended = 'High community confirmation: 5+ citizens confirmed.';
} else if (count >= 1) {
  classification = 'COMMUNITY_CONFIRMED';
  attention = 'STANDARD';
  action = 'COMMUNITY_CONFIRMED_LOG';
  recommended = 'Community confirmation recorded in public feed.';
}

return [{
  json: {
    ...$input.item.json,
    impact_classification: classification,
    attention_level: attention,
    action_taken: action,
    recommended_action: recommended
  }
}];

// SLA & Status Transition Engine
const item = $input.item.json;
const sla = item.sla_status || 'NORMAL';
const status = (item.status || '').toUpperCase();
let action = 'STATUS_TRACKED';
let attention = 'STANDARD';
let recommended = `Status updated to ${status}.`;

if (sla === 'SLA_BREACH_WARNING') {
  attention = 'CRITICAL';
  action = 'SLA_BREACH_ALERT';
  recommended = `⚠️ SLA Breach Warning: Grievance has been unresolved for ${item.age_hours || 0} hours. Officer fast-track required.`;
} else if (sla === 'APPROACHING_SLA') {
  attention = 'HIGH';
  action = 'SLA_APPROACHING_REMINDER';
  recommended = `⏳ Approaching SLA Deadline: Grievance pending for ${item.age_hours || 0} hours.`;
}

return [{
  json: {
    ...item,
    attention_level: attention,
    action_taken: action,
    recommended_action: recommended
  }
}];

// Resolution & Citizen Follow-Up Engine
const item = $input.item.json;

return [{
  json: {
    ...item,
    attention_level: 'STANDARD',
    action_taken: 'RESOLUTION_AUTOMATION_COMPLETED',
    recommended_action: 'Resolution logged in public feed. Citizen satisfaction survey prepared.',
    followup_event: 'RESOLUTION_FOLLOWUP_PENDING',
    followup_payload: {
      tracking_id: item.tracking_id,
      citizen_survey_url: `/feed/${item.grievance_id}`,
      resolution_remarks: item.latest_remarks || 'Issue resolved by field officer',
      resolved_at: new Date().toISOString()
    }
  }
}];

// Multi-Department Operational Routing & Audit Payload
const item = $input.item.json;
const dept = (item.department || 'General').toLowerCase();

let departmentQueue = 'General_Municipal_Operations';
if (dept.includes('water') || dept.includes('sanitation')) {
  departmentQueue = 'Water_Sanitation_Dispatch';
} else if (dept.includes('road') || dept.includes('public_work') || dept.includes('works')) {
  departmentQueue = 'Public_Works_Roads_Dispatch';
} else if (dept.includes('electric') || dept.includes('power')) {
  departmentQueue = 'Electricity_Board_Dispatch';
} else if (dept.includes('waste') || dept.includes('garbage')) {
  departmentQueue = 'Solid_Waste_Management_Dispatch';
} else if (dept.includes('health')) {
  departmentQueue = 'Public_Health_Sanitation_Dispatch';
}

const auditRecord = {
  automation: 'CivicOS Hackathon-Grade Smart Orchestrator v2.0',
  event_id: item.event_id,
  event: item.event,
  tracking_id: item.tracking_id,
  department: item.department,
  department_queue: departmentQueue,
  priority: item.priority,
  urgency_score: item.urgency_score,
  community_count: item.community_count || 0,
  impact_classification: item.impact_classification || 'NO_CONFIRMATION',
  sla_status: item.sla_status || 'NORMAL',
  attention_level: item.attention_level || 'STANDARD',
  action_taken: item.action_taken || 'PROCESSED',
  recommended_action: item.recommended_action,
  followup_event: item.followup_event || null,
  timestamp: new Date().toISOString(),
  source: 'n8n-CivicOS-Engine'
};

return [{
  json: {
    ...item,
    department_queue: departmentQueue,
    audit: auditRecord
  }
}];
